export type ParsedDepositRevenueInstruction<
  TProgram extends string = typeof ACCRUE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    manager: TAccountMetas[0];
    config: TAccountMetas[1];
    mint: TAccountMetas[2];
    usdcMint: TAccountMetas[3];
    managerUsdc: TAccountMetas[4];
    vault: TAccountMetas[5];
    /**
     * manager may deposit from the treasury itself, and Anchor rejects the same
     * writable account appearing twice as a typed account.
     */
    treasury: TAccountMetas[6];
    usdcTokenProgram: TAccountMetas[7];
  };
  data: DepositRevenueInstructionData;
};

export function parseDepositRevenueInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedDepositRevenueInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 8) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 8,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      manager: getNextAccount(),
      config: getNextAccount(),
      mint: getNextAccount(),
      usdcMint: getNextAccount(),
      managerUsdc: getNextAccount(),
      vault: getNextAccount(),
      treasury: getNextAccount(),
      usdcTokenProgram: getNextAccount(),
    },
    data: getDepositRevenueInstructionDataDecoder().decode(instruction.data),
  };
}
